window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[284]={"id":"284","numero":284,"titre":"Syndrome de l'intestin irritable (SII)","objectifs":[{"id":"284-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition du syndrome de l'intestin irritable (SII) et les différents sous types","contenu":"<p>Le <span class=\"kw-def\">syndrome de l'intestin irritable (SII)</span> est un <span class=\"kw-def\">trouble fonctionnel intestinal</span> défini par des critères <span class=\"kw-clinique\">exclusivement cliniques</span> (<span class=\"kw-def\">critères de</span> <span class=\"kw-def\">Rome IV</span>) : il n'existe <span class=\"kw-alerte\">aucun marqueur biologique</span> ni <span class=\"kw-alerte\">morphologique</span> du SII. Le diagnostic repose sur la coexistence de trois éléments :</p>\n      <ul>\n        <li><span class=\"kw-alerte\">Absence de toute maladie organique digestive</span> ;</li>\n        <li><span class=\"kw-clinique\">Douleurs abdominales chroniques</span> ;</li>\n        <li><span class=\"kw-clinique\">Troubles du transit fluctuants</span>.</li>\n      </ul>\n      <p>Ce sont <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">troubles du transit</span> qui définissent les <strong>4 sous-types</strong> de SII (selon l'échelle de <span class=\"kw-def\">Bristol</span>) :</p>\n      <table >\n        <thead>\n          <tr><th>Sous-type</th><th>Transit prédominant</th><th><span class=\"kw-def\">Score</span> de Bristol</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">SII-D</span></td><td><span class=\"kw-clinique\">Diarrhée</span> prédominante</td><td>Plutôt <span class=\"kw-def\">Bristol</span> <span class=\"kw-chiffre\">6-7</span></td></tr>\n          <tr><td><span class=\"kw-def\">SII-C</span></td><td><span class=\"kw-clinique\">Constipation</span> prédominante</td><td>Plutôt <span class=\"kw-def\">Bristol</span> <span class=\"kw-chiffre\">1-2</span></td></tr>\n          <tr><td><span class=\"kw-def\">SII-A</span></td><td>Alternance <span class=\"kw-clinique\">diarrhée</span> / <span class=\"kw-clinique\">constipation</span></td><td>—</td></tr>\n          <tr><td><span class=\"kw-def\">SII-I</span></td><td>SII indéterminé — n'entre dans aucun des 3 sous-types</td><td>—</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">📌 Le SII <span class=\"kw-alerte\">altère la qualité de vie</span> mais <span class=\"kw-alerte\">n'engage jamais le pronostic vital</span> — c'est une pathologie <span class=\"kw-alerte\">bénigne</span> mais <span class=\"kw-clinique\">chronique</span>.</div>","frequence":0},{"id":"284-2","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les critères diagnostiques des troubles fonctionnels intestinaux","contenu":"<p>Le <span class=\"kw-def\">diagnostic positif</span> du <span class=\"kw-def\">SII</span> — en tant que <span class=\"kw-def\">trouble fonctionnel intestinal</span> — repose sur <span class=\"kw-clinique\">les</span> <span class=\"kw-def\">critères de</span> <span class=\"kw-def\">Rome IV</span>, qui combinent une condition de <strong>durée</strong>, une condition de <strong>fréquence</strong> et un <strong>faisceau de critères sémiologiques</strong>.</p>\n      <ul>\n        <li><strong>Durée :</strong> <span class=\"kw-clinique\">symptômes</span> évoluant depuis <span class=\"kw-chiffre\">≥ 6 mois</span> avant de pouvoir poser le diagnostic ;</li>\n        <li><strong>Fréquence :</strong> <span class=\"kw-clinique\">douleur abdominale récidivante</span> survenant <span class=\"kw-chiffre\">≥ 1 fois/semaine</span> au cours des <span class=\"kw-chiffre\">3 derniers mois</span>.</li>\n      </ul>\n      <p>Il faut en outre la présence d'<span class=\"kw-chiffre\">au moins 2 des 3 critères</span> suivants, la <span class=\"kw-clinique\">douleur abdominale</span> étant :</p>\n      <ul>\n        <li>en relation avec la <span class=\"kw-clinique\">défécation</span> ;</li>\n        <li>associée à une <span class=\"kw-clinique\">modification de l'aspect des selles</span> ;</li>\n        <li>associée à une <span class=\"kw-clinique\">modification de la fréquence des selles</span>.</li>\n      </ul>\n      <div class=\"callout callout-warn\">⚠️ Le critère sémiologique ex<span class=\"kw-chiffre\">ige</span> <span class=\"kw-chiffre\">≥ 2/3</span> des items — un seul critère ne suffit pas. C'est le triptyque <em><span class=\"kw-clinique\">durée</span> <span class=\"kw-chiffre\">≥ 6 mois</span> ; <span class=\"kw-clinique\">douleur</span> <span class=\"kw-chiffre\">≥ 1×/semaine</span> ; <span class=\"kw-chiffre\">≥ 2/3</span> critères</em> qu'il faut savoir restituer.</div>","frequence":1},{"id":"284-3","rang":"B","rubrique":"Prévalence","titre":"Connaître la prévalence et le retentissement sur la qualité de vie","contenu":"<p>Le <span class=\"kw-def\">SII</span> est l'un des <span class=\"kw-clinique\">premiers motifs de consultation en gastro-entérologie</span>.</p>\n      <table >\n        <thead>\n          <tr><th>Paramètre</th><th>Donnée</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Prévalence</span> mondiale (population générale)</td><td><span class=\"kw-chiffre\">4 %</span> (fourchette <span class=\"kw-chiffre\">5 à 15 %</span>)</td></tr>\n          <tr><td>Sex-ratio</td><td><span class=\"kw-clinique\">Prédominance féminine</span> (<span class=\"kw-chiffre\">70 %</span>)</td></tr>\n          <tr><td>Âge</td><td><span class=\"kw-clinique\">Sujet jeune</span> ; diagnostic souvent porté entre <span class=\"kw-chiffre\">30 et 40 ans</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Retentissement :</strong> la <span class=\"kw-clinique\">qualité de vie</span> peut être <span class=\"kw-alerte\">très fortement altérée</span> ; l'impact sur la <span class=\"kw-clinique\">productivité au travail</span> est largement démontré — <span class=\"kw-alerte\">arrêts de travail</span>, <span class=\"kw-alerte\">absentéisme</span>.</p>\n      <div class=\"callout callout-info\">📌 Malgré ce retentissement, le SII <span class=\"kw-alerte\">n'engage pas le pronostic vital</span> : c'est un <span class=\"kw-alerte\">problème de santé publique</span> par sa <span class=\"kw-clinique\">fréquence</span>, non par sa gravité.</div>","frequence":0},{"id":"284-4","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les caractéristiques cliniques","contenu":"<p>Le tableau clinique du SII associe une <span class=\"kw-clinique\">douleur abdominale</span>, des <span class=\"kw-clinique\">troubles du transit</span> et des <span class=\"kw-clinique\">symptômes associés</span>, dans un contexte évocateur.</p>\n      <table >\n        <thead>\n          <tr><th>Dimension</th><th>Caractéristiques</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-clinique\">Douleur abdominale</span><br><em>(symptôme principal)</em></td>\n            <td>\n              <strong><span class=\"kw-clinique\">Évolution</span> :</strong> <span class=\"kw-clinique\">intermittente</span>, par crises de quelques heures à quelques jours, <span class=\"kw-chiffre\">≥ 1×/semaine</span> ; <br>\n              <strong>Type :</strong> spasmes ; <br>\n              <strong>Topographie :</strong> surtout <span class=\"kw-clinique\">hypogastre</span> et <span class=\"kw-clinique\">fosse iliaque gauche</span> (plus rarement fosse iliaque droite, ép<span class=\"kw-chiffre\">iga</span>stre, hypochondres, ou tout le cadre colique) ; <br>\n              <strong>Horaire :</strong> souvent <span class=\"kw-clinique\">matinale</span> <em>(douleur « réveil-matin »)</em>, classiquement <span class=\"kw-clinique\">absente la nuit</span> ; <br>\n              <strong>Facteurs aggravants :</strong> <span class=\"kw-etio\">alimentation</span> (douleur post-prandiale) ; <span class=\"kw-etio\">stress</span> ; <span class=\"kw-etio\">anxiété</span> ; <br>\n              <strong>Facteurs soulageants :</strong> périodes de repos (vacances) ; <br>\n              <strong>Lien avec le transit :</strong> douleur modifiée — soulagée ou aggravée — par la défécation.\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\">Troubles du transit</span></td>\n            <td>\n              <strong>Formes :</strong> <span class=\"kw-clinique\">constipation</span> (<span class=\"kw-chiffre\">&lt; 3 selles/semaine</span> ou difficultés d'évacuation) ; <span class=\"kw-clinique\">diarrhée</span> (<span class=\"kw-chiffre\">≥ 3 selles/jour</span>) ; alternance ; <br>\n              <strong><span class=\"kw-clinique\">Diarrhée</span> motrice</strong> le plus souvent : selles <span class=\"kw-clinique\">post-prandiales</span>, molles à liquides ; <br>\n              <strong><span class=\"kw-clinique\">Syndrome de recherche</span> des toilettes :</strong> selles <span class=\"kw-clinique\">impérieuses</span>, imposant de repérer <span class=\"kw-clinique\">les</span> toilettes lors des déplacements.\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\">Symptômes associés</span></td>\n            <td>\n              <strong>Digestifs :</strong> <span class=\"kw-clinique\">ballonnement abdominal</span>, sensation de plénitude, inconfort abdominal ; <span class=\"kw-clinique\">dyspepsie</span> / <span class=\"kw-clinique\">pesanteur</span> ép<span class=\"kw-chiffre\">iga</span>strique, sensation de digestion lente, <span class=\"kw-clinique\">satiété précoce</span>, <span class=\"kw-alerte\">détresse</span> post-prandiale (envie de sieste) ; <span class=\"kw-clinique\">RGO</span> sans œsophagite (« œsophage irritable ») ; <br>\n              <strong>Extradigestifs <em>(témoins d'un SII plus sévère)</em> :</strong> <span class=\"kw-clinique\">céphalées</span> ; <span class=\"kw-clinique\">myalgies</span> ; <span class=\"kw-clinique\">arthralgies</span> ; <span class=\"kw-clinique\">asthénie</span> ; bouffées de chaleur ; <span class=\"kw-clinique\">pollakiurie</span> ; dyspareunie ; <br>\n              <strong><span class=\"kw-def\">Comorbidités</span> :</strong> <span class=\"kw-etio\">fibromyalgie</span> ; <span class=\"kw-etio\">syndrome de fatigue chronique</span>.\n            </td>\n          </tr>\n          <tr>\n            <td>Arguments cliniques <strong>en faveur</strong></td>\n            <td>\n              <span class=\"kw-clinique\">Absence d'altération de l'état général</span> (pas d'<span class=\"kw-clinique\">amaigrissement</span>) ; <br>\n              <span class=\"kw-clinique\">Examen clinique normal</span>, contrastant avec l'intensité des symptômes — la <span class=\"kw-clinique\">palpation abdominale</span> pouvant néanmoins réveiller la douleur ; <br>\n              Ancienneté des symptômes, dont <span class=\"kw-clinique\">les</span> caractères se sont peu modifiés ; <br>\n              Contexte psychologique (personnalité anxieuse, dépressive) ; <br>\n              Influence nette du <span class=\"kw-etio\">stress</span> et des événements de vie sur les symptômes.\n            </td>\n          </tr>\n        </tbody>\n      </table>","frequence":0},{"id":"284-5","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les éléments cliniques devant amener à la réalisation d’une coloscopie pour éliminer une organicité","contenu":"<p><span class=\"kw-clinique\">Les</span> <strong><span class=\"kw-alerte\">signes d'alarme</span></strong> sont les éléments qui font <span class=\"kw-alerte\">sortir du cadre du SII</span> et imposent de rechercher une <span class=\"kw-alerte\">organicité</span> (en pratique : <span class=\"kw-imagerie\">coloscopie</span>). Leur présence rend le diagnostic de SII non recevable tant qu'une cause organique n'a pas été éliminée.</p>\n      <ul>\n        <li>Âge de survenue des symptômes <span class=\"kw-chiffre\">&gt; 50 ans</span> ;</li>\n        <li><span class=\"kw-alerte\">Terrain à risque de néoplasie colique</span> (ex. ATCD familial de cancer colorectal) ;</li>\n        <li>Symptomatologie <span class=\"kw-clinique\">diarrhéique</span> ;</li>\n        <li><span class=\"kw-clinique\">Amaigrissement</span> ;</li>\n        <li><span class=\"kw-alerte\">Sang dans les selles</span> : <span class=\"kw-clinique\">rectorragies</span>, <span class=\"kw-clinique\">méléna</span> ;</li>\n        <li>Symptômes <span class=\"kw-alerte\">nocturnes</span> ;</li>\n        <li>Apparition récente ou modification des symptômes ;</li>\n        <li>Anomalie à l'examen clinique : <span class=\"kw-clinique\">masse abdominale</span>, <span class=\"kw-clinique\">perte de poids</span> ;</li>\n        <li><span class=\"kw-bio\">Anomalie biologique</span> : anémie, <span class=\"kw-def\">syndrome inflammatoire</span>.</li>\n      </ul>\n      <div class=\"callout callout-danger\">🚩 <strong><span class=\"kw-alerte\">Drapeaux rouges</span></strong> — un seul de ces éléments suffit à imposer la <span class=\"kw-imagerie\">coloscopie</span> : <span class=\"kw-chiffre\">âge &gt; 50 ans</span> ; <span class=\"kw-clinique\">amaigrissement</span> ; <span class=\"kw-alerte\">rectorragies / méléna</span> ; <span class=\"kw-bio\">anémie ou syndrome inflammatoire</span> ; <span class=\"kw-clinique\">masse</span> abdominale ; ATCD familial de cancer colorectal ; symptômes nocturnes ou d'apparition récente.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 301 — Tumeur colon - rectum</em></p>","frequence":0},{"id":"284-6","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les indications de la coloscopie et les modalités de réalisation","contenu":"<div class=\"callout callout-warn\">⚠️ Il n'existe <span class=\"kw-alerte\">aucun marqueur biologique ou morphologique</span> du SII : la paraclinique ne sert <strong>qu'à éliminer <span class=\"kw-clinique\">les</span> autres causes</strong>, jamais à « prouver » le SII.</div>\n      <table >\n        <thead>\n          <tr><th>Examen</th><th>Indication</th><th>Objectif / modalités</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-imagerie\">Coloscopie</span></td>\n            <td>Présence d'un <span class=\"kw-alerte\">signe d'alarme</span></td>\n            <td>Réalisée <strong>sous AG</strong>, après préparation colique. Si <span class=\"kw-def\">SII-D</span> : <span class=\"kw-bio\">biopsies</span> étagées du côlon (rechercher une <span class=\"kw-etio\">colite microscopique</span>) <strong>+</strong> <span class=\"kw-bio\">biopsies</span> iléales (rechercher une <span class=\"kw-etio\">maladie de Crohn iléale</span>)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-imagerie\">EOGD + biopsies</span></td>\n            <td>Dyspepsie associée ; anémie ferriprive</td>\n            <td>Rechercher <span class=\"kw-etio\">H. pylori</span>, une atrophie duodénale, <span class=\"kw-etio\">Giardia duodenalis</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-bio\">Examens biologiques</span></td>\n            <td>Systématiques : <span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">CRP</span></td>\n            <td>Rechercher une anémie, un <span class=\"kw-def\">syndrome inflammatoire</span>. <br>Si <span class=\"kw-def\">SII-D</span> : <span class=\"kw-bio\">TSH</span> (éliminer une <span class=\"kw-etio\">hyperthyroïdie</span>) ; <span class=\"kw-bio\">Ac anti-transglutaminase</span> (<span class=\"kw-etio\">maladie cœliaque</span>) ; examen parasitologique des selles (lambliase)</td>\n          </tr>\n          <tr>\n            <td>Examens radiologiques (<span class=\"kw-imagerie\">échographie</span>, <span class=\"kw-imagerie\">TDM</span>)</td>\n            <td><span class=\"kw-alerte\">Aucune place</span> dans <span class=\"kw-clinique\">les</span> formes typiques</td>\n            <td>L'imagerie n'est pas indiquée devant un tableau typique de SII</td>\n          </tr>\n        </tbody>\n      </table>","frequence":1},{"id":"284-7","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les diagnostics différentiels et les examens complémentaires permettant de les éliminer","contenu":"<p>Aucun examen ne « prouve » le <span class=\"kw-def\">SII</span> : <span class=\"kw-clinique\">les</span> examens complémentaires servent à <strong>écarter les diagnostics différentiels</strong> évoqués selon le tableau clinique.</p>\n      <table >\n        <thead>\n          <tr><th><span class=\"kw-def\">Diagnostic différentiel</span></th><th>Examen permettant de l'éliminer</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">MICI</span> (<span class=\"kw-etio\">maladie de Crohn</span>, <span class=\"kw-etio\">RCH</span>)</td><td><span class=\"kw-imagerie\">Coloscopie</span> + <span class=\"kw-bio\">biopsies</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Cancer colorectal</span></td><td><span class=\"kw-imagerie\">Coloscopie</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Maladie cœliaque</span></td><td><span class=\"kw-bio\">Ac anti-transglutaminase</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Hyperthyroïdie</span></td><td><span class=\"kw-bio\">TSH</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Colite microscopique</span></td><td><span class=\"kw-imagerie\">Biopsies coliques étagées</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Parasitose</span> (giardiose / lambliase)</td><td><span class=\"kw-bio\">Examen parasitologique des selles</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Intolérance au lactose</span></td><td><span class=\"kw-bio\">Test respiratoire</span> (au lactose)</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 282 — <span class=\"kw-etio\">MICI</span> · 285 — <span class=\"kw-clinique\">Diarrhée</span> chronique · 301 — Tumeur colon - rectum · 242 — <span class=\"kw-etio\">Hyperthyroïdie</span></em></p>","frequence":0},{"id":"284-8","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes de la prise en charge thérapeutique","contenu":"<div class=\"callout callout-warn\">⚠️ L'objectif du traitement est d'<strong>améliorer <span class=\"kw-clinique\">les</span> symptômes et la qualité de vie</strong> — il ne permet <span class=\"kw-alerte\">pas de guérir</span> la maladie.</div>\n      <p>La prise en charge est multimodale et hiérarchisée.</p>\n      <table >\n        <thead>\n          <tr><th>Volet</th><th>Modalités</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-def\">Éducation thérapeutique</span></strong><br><em>(étape la plus importante)</em></td>\n            <td>\n              <strong>Information :</strong> nommer le diagnostic ; expliquer le caractère <span class=\"kw-alerte\">bénin</span> et <span class=\"kw-clinique\">chronique</span> ; <br>\n              <strong><span class=\"kw-def\">Physiopathologie</span> à expliquer :</strong> <span class=\"kw-etio\">altération de l'axe intestin-cerveau</span> ; <span class=\"kw-etio\">hypersensibilité viscérale</span> ; <span class=\"kw-etio\">troubles de la motricité intestinale</span> ; <span class=\"kw-etio\">dysbiose intestinale</span>.\n            </td>\n          </tr>\n          <tr>\n            <td>Prise en charge <strong>diététique</strong></td>\n            <td>\n              <strong>1ʳᵉ intention :</strong> conseils d'hygiène alimentaire simples — 3 repas/jour, manger lentement, éviter <span class=\"kw-clinique\">les</span> aliments trop gras, fibres si <span class=\"kw-clinique\">constipation</span> ; <br>\n              <strong>Si insuffisant :</strong> <span class=\"kw-ttt\">régime pauvre en FODMAPs</span>, encadré par une diététicienne, sur une durée de <span class=\"kw-chiffre\">4 à 8 semaines</span>, quel que soit le phénotype du SII.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Antalgie</strong></td>\n            <td><span class=\"kw-ttt\">Antispasmodiques</span> en 1ʳᵉ intention <em>(<span class=\"kw-clinique\">douleur abdominale</span> + ballonnement sans distension)</em> : <span class=\"kw-ttt\">alvérine + siméthicone</span> ; <span class=\"kw-ttt\">trimébutine</span> ; <span class=\"kw-ttt\">phloroglucinol</span> ; <span class=\"kw-ttt\">pinavérium</span></td>\n          </tr>\n          <tr>\n            <td>Action sur le <strong>transit</strong></td>\n            <td>\n              <strong>Si <span class=\"kw-clinique\">constipation</span> :</strong> <span class=\"kw-ttt\">laxatifs osmotiques</span> (macrogol) ou <span class=\"kw-ttt\">laxatifs de lest</span> (ispaghul) ; <br>\n              <strong>Si <span class=\"kw-clinique\">diarrhée</span> :</strong> <span class=\"kw-ttt\">ralentisseurs du transit</span> (<span class=\"kw-ttt\">lopéramide</span>).\n            </td>\n          </tr>\n          <tr>\n            <td>Prise en charge <strong>psychologique</strong></td>\n            <td>Psychologue ; psychiatre (recours possible aux <span class=\"kw-ttt\">antidépresseurs</span> — <span class=\"kw-ttt\">tricycliques</span> tels que l'<span class=\"kw-ttt\">amitriptyline</span>, ou <span class=\"kw-ttt\">ISRS</span> tels que l'<span class=\"kw-ttt\">escitalopram</span>) ; hypnose ; thérapies cognitivo-comportementales (TCC) ; groupe de parole ; activité physique</td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 283 — <span class=\"kw-clinique\">Constipation</span></em></p>","frequence":0}],"astuces":[],"strategie":{"redflags":"<p><strong>Règle :</strong> un seul de ces <span class=\"kw-alerte\">signes d'alarme</span> fait <span class=\"kw-alerte\">sortir du cadre du SII</span> et impose une <span class=\"kw-imagerie\">coloscopie</span> pour éliminer une <span class=\"kw-alerte\">organicité</span> — le diagnostic de SII reste irrecevable tant qu'une cause organique n'est pas écartée.</p><ul><li>Âge de survenue des symptômes <span class=\"kw-chiffre\">&gt; 50 ans</span></li><li><span class=\"kw-etio\">Terrain à risque de néoplasie colique</span> (ATCD familial de <span class=\"kw-etio\">cancer colorectal</span>)</li><li>Symptomatologie <span class=\"kw-clinique\">diarrhéique</span></li><li><span class=\"kw-clinique\">Amaigrissement</span> / <span class=\"kw-alerte\">altération de l'état général</span></li><li><span class=\"kw-alerte\">Sang dans les selles</span> : <span class=\"kw-clinique\">rectorragies</span>, <span class=\"kw-clinique\">méléna</span></li><li>Symptômes <span class=\"kw-alerte\">nocturnes</span></li><li><span class=\"kw-alerte\">Apparition récente</span> ou <span class=\"kw-alerte\">modification</span> des symptômes</li><li>Anomalie à l'examen clinique : <span class=\"kw-clinique\">masse abdominale</span>, <span class=\"kw-clinique\">perte de poids</span></li><li><span class=\"kw-bio\">Anomalie biologique</span> : <span class=\"kw-bio\">anémie</span>, <span class=\"kw-def\">syndrome inflammatoire</span></li></ul>","principes":"<p><strong>Objectif :</strong> améliorer <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">symptômes</span> et la <span class=\"kw-clinique\">qualité de vie</span> — le traitement <span class=\"kw-alerte\">ne guérit pas</span> la maladie (<span class=\"kw-def\">SII</span> <span class=\"kw-alerte\">bénin</span> mais <span class=\"kw-clinique\">chronique</span>). L'<span class=\"kw-def\">éducation thérapeutique</span> est l'étape la plus importante.</p><p><strong><span class=\"kw-def\">Éducation thérapeutique</span> <span class=\"q\">— étape la plus importante</span></strong></p><ul><li>Nommer le diagnostic ; expliquer le caractère <span class=\"kw-alerte\">bénin</span> et <span class=\"kw-clinique\">chronique</span></li><li>Expliquer la <span class=\"kw-def\">physiopathologie</span> : <span class=\"kw-etio\">altération de l'axe intestin-cerveau</span> · <span class=\"kw-etio\">hypersensibilité viscérale</span> · <span class=\"kw-etio\">troubles de la motricité intestinale</span> · <span class=\"kw-etio\">dysbiose intestinale</span></li></ul><p><strong>Mesures diététiques</strong></p><ul><li><strong>1ʳᵉ intention :</strong> conseils d'hygiène alimentaire simples (3 repas/j, manger lentement, éviter <span class=\"kw-clinique\">les</span> aliments trop gras, <span class=\"kw-ttt\">fibres</span> si <span class=\"kw-clinique\">constipation</span>)</li><li><strong>Si insuffisant :</strong> <span class=\"kw-ttt\">régime pauvre en FODMAPs</span> encadré par une diététicienne, <span class=\"kw-chiffre\">4 à 8 semaines</span>, quel que soit le phénotype du SII</li></ul><p><strong>Antalgie</strong></p><ul><li><span class=\"kw-ttt\">Antispasmodiques</span> en 1ʳᵉ intention (<span class=\"kw-clinique\">douleur abdominale</span> + ballonnement sans distension)</li><li><span class=\"kw-ttt\">Alvérine + siméthicone</span> · <span class=\"kw-ttt\">trimébutine</span> · <span class=\"kw-ttt\">phloroglucinol</span> · <span class=\"kw-ttt\">pinavérium</span></li></ul><p><strong>Action sur le transit</strong></p><ul><li>Si <span class=\"kw-clinique\">constipation</span> : <span class=\"kw-ttt\">laxatifs osmotiques</span> (macrogol) ou <span class=\"kw-ttt\">laxatifs de lest</span> (ispaghul)</li><li>Si <span class=\"kw-clinique\">diarrhée</span> : <span class=\"kw-ttt\">ralentisseurs du transit</span> (<span class=\"kw-ttt\">lopéramide</span>)</li></ul><p><strong>Prise en charge psychologique</strong></p><ul><li>Recours possible aux <span class=\"kw-ttt\">antidépresseurs</span> : <span class=\"kw-ttt\">tricycliques</span> (amitriptyline) ou <span class=\"kw-ttt\">ISRS</span> (escitalopram)</li><li><span class=\"kw-ttt\">Thérapies cognitivo-comportementales (TCC)</span> · <span class=\"kw-ttt\">hypnose</span> · <span class=\"kw-ttt\">activité physique</span> · groupe de parole</li></ul>"},"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Douleur abdominale chronique + troubles du transit fluctuants — Suspicion de SII — critères de Rome IV (≥ 6 mois ; douleur ≥ 1×/sem ; ≥ 2/3 critères)","detail":"<h4>CAT — <span class=\"kw-clinique\">syndrome de l</span>'intestin irritable — Éliminer une organicité, puis traiter selon le sous-type</h4>","branches":[{"to":"t-organicite","label":"Au moins un signe d'alarme présent","color":"amber"},{"to":"q-soustype","label":"Aucun signe d'alarme → SII confirmé","color":"green"}]},{"id":"t-organicite","kind":"terminal","label":"Rechercher une organicité — coloscopie","color":"amber","detail":"<h4>Signes d'alarme</h4><ul><li><span class=\"kw-chiffre\">Âge &gt; 50 ans</span>, <span class=\"kw-clinique\">amaigrissement</span>, symptômes <span class=\"kw-alerte\">nocturnes</span> ou d'apparition récente</li><li><span class=\"kw-alerte\">Rectorragies</span> / <span class=\"kw-alerte\">méléna</span>, <span class=\"kw-bio\">anémie</span> ou <span class=\"kw-def\">syndrome inflammatoire</span></li><li><span class=\"kw-clinique\">Masse abdominale</span>, ATCD familial de <span class=\"kw-etio\">cancer colorectal</span></li></ul><h4><span class=\"kw-imagerie\">Coloscopie</span></h4><ul><li>Réalisée <strong>sous AG</strong>, après préparation colique</li><li>Si <span class=\"kw-def\">SII-D</span> : <span class=\"kw-bio\">biopsies</span> étagées du côlon (<span class=\"kw-etio\">colite microscopique</span>) + iléales (<span class=\"kw-etio\">maladie de Crohn</span> iléale)</li></ul><h4>Examens associés</h4><ul><li><span class=\"kw-imagerie\">EOGD</span> + <span class=\"kw-bio\">biopsies</span> si dyspepsie / anémie ferriprive (<span class=\"kw-etio\">H. pylori</span>, <span class=\"kw-etio\">Giardia duodenalis</span>)</li><li><span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">CRP</span> systématiques ; si SII-D : <span class=\"kw-bio\">TSH</span> (<span class=\"kw-etio\">hyperthyroïdie</span>), <span class=\"kw-bio\">Ac anti-transglutaminase</span> (<span class=\"kw-etio\">maladie cœliaque</span>), <span class=\"kw-bio\">examen parasitologique des selles</span></li></ul><h4>Renvoi</h4><ul><li>Item 282 (<span class=\"kw-clinique\">MICI</span>) · Item 285 (<span class=\"kw-clinique\">Diarrhée</span> chronique) · Item 301 (Tumeur colon - rectum)</li></ul>"},{"id":"q-soustype","kind":"decision","label":"Sous-type / symptôme prédominant ? — Socle commun à tous : éducation thérapeutique + règles hygiéno-diététiques (± FODMAPs)","branches":[{"to":"t-sii-c","label":"Constipation prédominante (SII-C)","color":"green"},{"to":"t-sii-d","label":"Diarrhée prédominante (SII-D)","color":"green"},{"to":"t-douleur","label":"Douleur / ballonnement au premier plan","color":"green"}]},{"id":"t-sii-c","kind":"terminal","label":"SII-C → laxatifs","color":"green","detail":"<h4>Transit</h4><ul><li><span class=\"kw-ttt\">Laxatifs osmotiques</span> (macrogol) ou <span class=\"kw-ttt\">laxatifs de lest</span> (ispaghul)</li><li>Apport en <span class=\"kw-ttt\">fibres</span></li></ul><h4>Socle commun</h4><ul><li><span class=\"kw-def\">Éducation thérapeutique</span> + <span class=\"kw-ttt\">RHD</span> ; <span class=\"kw-ttt\">régime pauvre en FODMAPs</span> (<span class=\"kw-chiffre\">4-8 semaines</span>) si insuffisant</li></ul>"},{"id":"t-sii-d","kind":"terminal","label":"SII-D → ralentisseurs du transit","color":"green","detail":"<h4>Transit</h4><ul><li><span class=\"kw-ttt\">Ralentisseurs du transit</span> (<span class=\"kw-ttt\">lopéramide</span>)</li></ul><h4>Socle commun</h4><ul><li><span class=\"kw-def\">Éducation thérapeutique</span> + <span class=\"kw-ttt\">RHD</span> ; <span class=\"kw-ttt\">régime pauvre en FODMAPs</span> (<span class=\"kw-chiffre\">4-8 semaines</span>) si insuffisant</li></ul>"},{"id":"t-douleur","kind":"terminal","label":"Douleur / ballonnement → antispasmodiques","color":"green","detail":"<h4>Antalgie</h4><ul><li><span class=\"kw-ttt\">Antispasmodiques</span> en 1ʳᵉ intention (<span class=\"kw-ttt\">alvérine + siméthicone</span>, <span class=\"kw-ttt\">trimébutine</span>, <span class=\"kw-ttt\">phloroglucinol</span>, <span class=\"kw-ttt\">pinavérium</span>)</li></ul><h4>Si insuffisant</h4><ul><li><span class=\"kw-ttt\">Régime pauvre en FODMAPs</span> (<span class=\"kw-chiffre\">4-8 semaines</span>)</li><li>PEC psychologique : <span class=\"kw-ttt\">antidépresseurs</span> (<span class=\"kw-ttt\">tricycliques</span> / <span class=\"kw-ttt\">ISRS</span>), <span class=\"kw-ttt\">TCC</span>, <span class=\"kw-ttt\">hypnose</span></li></ul>"}]},"cards":[{"i":"afb8b1998292","n":284,"o":"284-1","u":"Définition","t":"Connaître la définition du syndrome de l'intestin irritable (SII) et les différents sous types","q":"Quel est l'impact pronostique du syndrome de l'intestin irritable (SII) pour le patient ?","a":"<p>Le syndrome de l'intestin irritable (SII) <strong>altère la qualité de vie</strong> du patient, mais il <strong>n'engage jamais le pronostic vital</strong>. C'est une pathologie <strong>bénigne mais chronique</strong>.</p>"},{"i":"baf636d3c396","n":284,"o":"284-1","u":"Définition","t":"Connaître la définition du syndrome de l'intestin irritable (SII) et les différents sous types","q":"Comment est défini le syndrome de l'intestin irritable (SII) et sur quels critères repose son diagnostic ?","a":"<p>Le syndrome de l'intestin irritable (SII) est un <strong>trouble fonctionnel intestinal</strong> défini par des <strong>critères exclusivement cliniques (critères de Rome IV)</strong>. Il n'existe <strong>aucun marqueur biologique ni morphologique</strong> du SII. Le diagnostic repose sur la coexistence de trois éléments :</p><ul><li>Absence de toute maladie organique digestive</li><li>Douleurs abdominales chroniques</li><li>Troubles du transit fluctuants</li></ul>"},{"i":"ec8edf8db35e","n":284,"o":"284-1","u":"Définition","t":"Connaître la définition du syndrome de l'intestin irritable (SII) et les différents sous types","q":"Quels sont les différents sous-types du syndrome de l'intestin irritable (SII) et comment sont-ils définis ?","a":"<p>Les sous-types du SII sont définis par les <strong>troubles du transit</strong>, selon l'échelle de Bristol :</p><ul><li><strong>SII-D</strong> (Diarrhée prédominante) : transit de type <strong>Bristol 6-7</strong>.</li><li><strong>SII-C</strong> (Constipation prédominante) : transit de type <strong>Bristol 1-2</strong>.</li><li><strong>SII-A</strong> (Alternance diarrhée/constipation).</li><li><strong>SII-I</strong> (Indéterminé) : n'entre dans aucun des 3 sous-types précédents.</li></ul>"},{"i":"2634f95330ea","n":284,"o":"284-2","u":"Diagnostic positif","t":"Connaître les critères diagnostiques des troubles fonctionnels intestinaux","q":"Quelle est la condition de durée requise par les critères de Rome IV pour le diagnostic de Syndrome de l'Intestin Irritable (SII) ?","a":"<p>Les symptômes doivent évoluer depuis <strong>au moins 6 mois</strong> avant de pouvoir poser le diagnostic de SII.</p>"},{"i":"6b307d2e508a","n":284,"o":"284-2","u":"Diagnostic positif","t":"Connaître les critères diagnostiques des troubles fonctionnels intestinaux","q":"Quelle est la condition de fréquence des douleurs abdominales requise par les critères de Rome IV pour le diagnostic de Syndrome de l'Intestin Irritable (SII) ?","a":"<p>Une douleur abdominale récidivante doit survenir <strong>au moins une fois par semaine</strong> au cours des <strong>3 derniers mois</strong>.</p>"},{"i":"a1699d59c700","n":284,"o":"284-2","u":"Diagnostic positif","t":"Connaître les critères diagnostiques des troubles fonctionnels intestinaux","q":"Quels sont les critères sémiologiques associés à la douleur abdominale qui doivent être présents pour le diagnostic de Syndrome de l'Intestin Irritable (SII) selon les critères de Rome IV ?","a":"<p>Il faut la présence d'<strong>au moins 2 des 3 critères</strong> suivants, associés à la douleur abdominale :</p><ul><li>En relation avec la <strong>défécation</strong>.</li><li>Associée à une modification de l'<strong>aspect des selles</strong>.</li><li>Associée à une modification de la <strong>fréquence des selles</strong>.</li></ul>"},{"i":"bd550d80c76a","n":284,"o":"284-2","u":"Diagnostic positif","t":"Connaître les critères diagnostiques des troubles fonctionnels intestinaux","q":"Sur quels critères diagnostiques le Syndrome de l'Intestin Irritable (SII) repose-t-il, selon les recommandations actuelles ?","a":"<p>Le diagnostic positif du Syndrome de l'Intestin Irritable (SII) repose sur les <strong>critères de Rome IV</strong>.</p>"},{"i":"2b682f845123","n":284,"o":"284-4","u":"Diagnostic positif","t":"Connaître les caractéristiques cliniques","q":"Quels sont les symptômes associés, digestifs et extra-digestifs, du Syndrome de l'Intestin Irritable (SII) ?","a":"<p>Les symptômes associés au SII sont :<ul><li><strong>Digestifs</strong> : <strong>ballonnement abdominal</strong>, sensation de plénitude, inconfort abdominal, dyspepsie, pesanteur épigastrique, sensation de digestion lente, satiété précoce, détresse post-prandiale, et RGO sans œsophagite.</li><li><strong>Extra-digestifs</strong> (témoins d'un SII plus sévère) : <strong>céphalées</strong>, myalgies, arthralgies, <strong>asthénie</strong>, bouffées de chaleur, pollakiurie, dyspareunie.</li><li><strong>Comorbidités</strong> : fibromyalgie, syndrome de fatigue chronique.</li></ul></p>"},{"i":"5cf60537749e","n":284,"o":"284-4","u":"Diagnostic positif","t":"Connaître les caractéristiques cliniques","q":"Quels sont les facteurs modulant la douleur abdominale dans le Syndrome de l'Intestin Irritable (SII) ?","a":"<p>Les facteurs modulants la douleur abdominale dans le SII sont :<ul><li><strong>Aggravants</strong> : l'<strong>alimentation</strong> (douleur post-prandiale), le <strong>stress</strong>, l'<strong>anxiété</strong>.</li><li><strong>Soulageants</strong> : les <strong>périodes de repos</strong> (vacances).</li><li><strong>Lien avec le transit</strong> : la douleur est <strong>modifiée par la défécation</strong> (soulagée ou aggravée).</li></ul></p>"},{"i":"c540cba45560","n":284,"o":"284-4","u":"Diagnostic positif","t":"Connaître les caractéristiques cliniques","q":"Quelle est la caractéristique principale de la douleur abdominale dans le Syndrome de l'Intestin Irritable (SII) ?","a":"<p>La douleur abdominale dans le SII est <strong>intermittente</strong>, survenant par <strong>crises de quelques heures à quelques jours</strong>, et elle est présente <strong>au moins une fois par semaine</strong>. Elle est souvent de type <strong>spasmodique</strong>, localisée principalement à l'<strong>hypogastre</strong> et à la <strong>fosse iliaque gauche</strong>, et typiquement <strong>absente la nuit</strong>.</p>"},{"i":"eccfe3aaf377","n":284,"o":"284-4","u":"Diagnostic positif","t":"Connaître les caractéristiques cliniques","q":"Quels arguments cliniques orientent spécifiquement vers le diagnostic de Syndrome de l'Intestin Irritable (SII) ?","a":"<p>Certains arguments cliniques orientent vers le SII :<ul><li>Absence d'<strong>altération de l'état général</strong> (<strong>pas d'amaigrissement</strong>).</li><li>Un <strong>examen clinique normal</strong> contrastant avec l'intensité des symptômes (la palpation abdominale pouvant réveiller la douleur).</li><li>Une <strong>ancienneté des symptômes</strong>, dont les caractères se sont peu modifiés.</li><li>Un <strong>contexte psychologique</strong> évocateur (personnalité anxieuse, dépressive).</li><li>Une <strong>influence nette du stress</strong> et des événements de vie sur les symptômes.</li></ul></p>"},{"i":"fa2f52008adf","n":284,"o":"284-4","u":"Diagnostic positif","t":"Connaître les caractéristiques cliniques","q":"Comment se manifestent les troubles du transit dans le Syndrome de l'Intestin Irritable (SII) ?","a":"<p>Les troubles du transit dans le SII peuvent prendre la forme de :<ul><li><strong>Constipation</strong> : <strong>moins de 3 selles par semaine</strong> ou <strong>difficultés d'évacuation</strong>.</li><li><strong>Diarrhée</strong> : <strong>au moins 3 selles par jour</strong>, souvent de type <strong>motrice</strong> (selles post-prandiales, molles à liquides) et s'accompagnant d'un <strong>syndrome de recherche des toilettes</strong> (selles impérieuses).</li><li>Une <strong>alternance</strong> de constipation et de diarrhée.</li></ul></p>"},{"i":"0202be80da9a","n":284,"o":"284-5","u":"Diagnostic positif","t":"Connaître les éléments cliniques devant amener à la réalisation d’une coloscopie pour éliminer une organicité","q":"Quelles sont les anomalies biologiques considérées comme des signes d'alarme, devant faire suspecter une pathologie organique et nécessiter une coloscopie, en présence de symptômes évoquant un SII ?","a":"<ul><li><strong>Anémie</strong></li><li><strong>Syndrome inflammatoire</strong> (biologique)</li></ul>"},{"i":"422d3fef3f5e","n":284,"o":"284-5","u":"Diagnostic positif","t":"Connaître les éléments cliniques devant amener à la réalisation d’une coloscopie pour éliminer une organicité","q":"En présence de symptômes évoquant un Syndrome de l'Intestin Irritable (SII), quelle est la conduite à tenir si un signe d'alarme est identifié ?","a":"<p>La présence d'un <strong>signe d'alarme</strong> impose de rechercher une organicité par des examens complémentaires, notamment une <strong>coloscopie</strong>, avant de pouvoir retenir le diagnostic de SII.</p>"},{"i":"bed900c84694","n":284,"o":"284-5","u":"Diagnostic positif","t":"Connaître les éléments cliniques devant amener à la réalisation d’une coloscopie pour éliminer une organicité","q":"Quels sont les signes d'alarme liés à l'âge ou aux antécédents, devant faire suspecter une pathologie organique et nécessiter une coloscopie, en présence de symptômes évoquant un SII ?","a":"<ul><li><strong>Âge de survenue des symptômes > 50 ans</strong></li><li><strong>Antécédent familial de cancer colorectal</strong> (terrain à risque de néoplasie colique)</li></ul>"},{"i":"f0a1f6106898","n":284,"o":"284-5","u":"Diagnostic positif","t":"Connaître les éléments cliniques devant amener à la réalisation d’une coloscopie pour éliminer une organicité","q":"Quels sont les signes d'alarme cliniques, autres que l'âge et les antécédents, devant faire suspecter une pathologie organique et nécessiter une coloscopie, en présence de symptômes évoquant un SII ?","a":"<ul><li><strong>Amaigrissement</strong></li><li><strong>Symptomatologie diarrhéique</strong> prédominante ou exclusive</li><li><strong>Sang dans les selles</strong> (rectorragies, méléna)</li><li><strong>Symptômes nocturnes</strong></li><li><strong>Apparition récente</strong> ou modification des symptômes</li><li>Anomalie à l'examen clinique : <strong>masse abdominale</strong>, perte de poids (confirmant l'amaigrissement)</li></ul>"},{"i":"28da9784e890","n":284,"o":"284-8","u":"Prise en charge","t":"Connaître les principes de la prise en charge thérapeutique","q":"Quel est l'objectif principal de la prise en charge thérapeutique du Syndrome de l'Intestin Irritable (SII) ?","a":"<p>L'objectif principal est d'<strong>améliorer les symptômes</strong> et la <strong>qualité de vie</strong> du patient. Il est important de noter que le traitement ne permet pas de guérir la maladie, qui est chronique et bénigne.</p>"},{"i":"7a9c4c9a3d48","n":284,"o":"284-8","u":"Prise en charge","t":"Connaître les principes de la prise en charge thérapeutique","q":"Quels sont les piliers de l'éducation thérapeutique dans la prise en charge du Syndrome de l'Intestin Irritable (SII) ?","a":"<ul><li><strong>Information</strong> : nommer le diagnostic, expliquer son caractère <strong>bénin et chronique</strong>.</li><li><strong>Physiopathologie</strong> : expliquer l'altération de l'axe intestin-cerveau, l'hypersensibilité viscérale, les troubles de la motricité intestinale et la dysbiose intestinale.</li></ul>"},{"i":"b2e2b39f7d48","n":284,"o":"284-8","u":"Prise en charge","t":"Connaître les principes de la prise en charge thérapeutique","q":"Quelles sont les options de prise en charge psychologique proposées pour le Syndrome de l'Intestin Irritable (SII) ?","a":"<p>La prise en charge psychologique peut inclure un suivi avec un psychologue ou un psychiatre, l'hypnose, les <strong>thérapies cognitivo-comportementales (TCC)</strong>, les groupes de parole, et la promotion d'une activité physique. Le recours aux <strong>antidépresseurs</strong> (tricycliques comme l'<strong>amitriptyline</strong> ou ISRS comme l'<strong>escitalopram</strong>) est également possible.</p>"},{"i":"c5ad5135fd54","n":284,"o":"284-8","u":"Prise en charge","t":"Connaître les principes de la prise en charge thérapeutique","q":"Quels sont les traitements antalgiques et modificateurs de transit recommandés dans le Syndrome de l'Intestin Irritable (SII) ?","a":"<ul><li><strong>Antalgiques</strong> (pour douleur abdominale et ballonnement sans distension) : <strong>antispasmodiques</strong> en 1<sup>re</sup> intention (alvérine + siméthicone, trimébutine, phloroglucinol, pinavérium).</li><li><strong>Transit</strong> :<ul><li>Si constipation : laxatifs <strong>osmotiques</strong> (macrogol) ou laxatifs de <strong>lest</strong> (ispaghul).</li><li>Si diarrhée : ralentisseurs du transit (<strong>lopéramide</strong>).</li></ul></li></ul>"},{"i":"d504ae32830f","n":284,"o":"284-8","u":"Prise en charge","t":"Connaître les principes de la prise en charge thérapeutique","q":"Quels sont les principes de la prise en charge diététique du Syndrome de l'Intestin Irritable (SII) ?","a":"<ul><li>En 1<sup>re</sup> intention : conseils d'hygiène alimentaire simples (3 repas/jour, manger lentement, éviter les aliments trop gras, fibres si constipation).</li><li>Si insuffisant : régime pauvre en <strong>FODMAPs</strong>, encadré par une diététicienne, sur une durée de <strong>4 à 8 semaines</strong>, quel que soit le phénotype du SII.</li></ul>"}]};